import "./ProblemTable.css";

export interface ProblemRow {
  title: string;
  pattern: string;
  minutes: number;
  review: string;
  due: boolean;
}

export interface ProblemTableProps {
  rows: readonly ProblemRow[];
}

export function ProblemTable({ rows }: ProblemTableProps) {
  return (
    <table className="myelin-problem-table">
      <caption className="myelin-problem-table__caption">Solved problems</caption>
      <thead>
        <tr>
          <th scope="col">Title</th>
          <th scope="col">Pattern</th>
          <th scope="col" className="myelin-problem-table__numeric">Minutes</th>
          <th scope="col">Next review</th>
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 ? (
          <tr>
            <td colSpan={4} className="myelin-problem-table__empty">
              No solved problems yet.
            </td>
          </tr>
        ) : (
          rows.map((row, index) => (
            <tr
              key={`${row.title}-${index}`}
              className="myelin-problem-table__row"
              tabIndex={0}
            >
              <td>{row.title}</td>
              <td>{row.pattern}</td>
              <td className="myelin-problem-table__numeric">{row.minutes}</td>
              <td
                className={
                  row.due
                    ? "myelin-problem-table__review myelin-problem-table__review--due"
                    : "myelin-problem-table__review"
                }
              >
                {row.review}
                {row.due && (
                  <span className="myelin-problem-table__due-label"> · due today</span>
                )}
              </td>
            </tr>
          ))
        )}
      </tbody>
    </table>
  );
}
```

