  --myelin-table-due-fg: #ffe08a;
}

.myelin-problem-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--myelin-table-bg);
  color: var(--myelin-table-fg);
  font-size: 0.95rem;
  line-height: 1.4;
}

.myelin-problem-table__caption {
  caption-side: top;
  text-align: left;
  padding: 0 0 0.5rem;
  color: var(--myelin-table-muted);
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.myelin-problem-table th,
.myelin-problem-table td {
  padding: 0.5rem 0.75rem;
  border-bottom: 1px solid var(--myelin-table-border);
  text-align: left;
  vertical-align: middle;
}

.myelin-problem-table thead th {
  background: var(--myelin-table-header-bg);
  font-weight: 600;
  color: var(--myelin-table-muted);
  position: sticky;
  top: 0;
}

.myelin-problem-table__numeric {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.myelin-problem-table__row:hover {
  background: var(--myelin-table-row-hover);
}

.myelin-problem-table__row:focus-visible {
  outline: 2px solid var(--myelin-table-focus);
  outline-offset: -2px;
}

.myelin-problem-table__review--due {
  background: var(--myelin-table-due-bg);
  color: var(--myelin-table-due-fg);
  font-weight: 600;
}

.myelin-problem-table__due-label {
  font-weight: 500;
}

.myelin-problem-table__empty {
  color: var(--myelin-table-muted);
  font-style: italic;
  text-align: center;
  padding: 1rem 0.75rem;
}
